package network.conet.chat.nativekey

import network.conet.chat.ConetChatCryptoUtil
import org.json.JSONObject
import org.junit.Assert.assertEquals
import org.junit.Assert.assertNotNull
import org.junit.Assert.assertNull
import org.junit.Test
import java.io.File

/**
 * Native EIP-712 (nativekey/Eip712.kt) against `spec/eip712-native-vectors.v1.json`, generated by ethers 6.16.0 with
 * `scripts/gen-eip712-native-vectors.mjs`. The digest, the signature and the address must all match. The EIP-712
 * specification example digest (0xbe609aee…57bd2) is checked separately as a known answer.
 */
class Eip712VectorsTest {
    private val v = JSONObject(
        String(File(System.getenv("EIP712_VECTORS") ?: "../spec/eip712-native-vectors.v1.json").readBytes(), Charsets.UTF_8),
    )
    private val key = ConetChatCryptoUtil.hexToBytes("78c08ce2d2b3fcc5674235d61587b11daebeb0bd4b44a263b827f0ba7743b0bd")!!

    @Test
    fun everyCaseMatchesEthers() {
        val cases = v.getJSONArray("cases")
        assertEquals(5, cases.length())
        for (i in 0 until cases.length()) {
            val c = cases.getJSONObject(i)
            val id = c.getString("id")
            val expect = c.getJSONObject("expect")
            val td = c.getJSONObject("typedData")
            val digest = Eip712.digest(td)
            assertNotNull("$id digest", digest)
            assertEquals("$id digest", expect.getString("digest"), ConetChatCryptoUtil.toHex(digest!!).let { "0x$it" })
            assertEquals("$id signature", expect.getString("signature"), Eip712.signTypedData(key, td))
            assertEquals("$id address", expect.getString("address"), WalletAddress.fromPrivateKey(key))
        }
    }

    @Test
    fun specificationExampleKnownDigest() {
        val mail = (0 until v.getJSONArray("cases").length())
            .map { v.getJSONArray("cases").getJSONObject(it) }
            .first { it.getString("id") == "EIP712-MAIL-SPEC" }
        val digest = ConetChatCryptoUtil.toHex(Eip712.digest(mail.getJSONObject("typedData"))!!)
        assertEquals("be609aee343fb3c4b28e1df9e632fca64fcfaede20f02e86244efddf30957bd2", digest)
    }

    @Test
    fun unsupportedInputIsRefusedAndNothingIsSigned() {
        val base = JSONObject(
            """{"domain":{"name":"A","chainId":1},"types":{"M":[{"name":"x","type":"uint256"}]},"primaryType":"M","message":{"x":"1"}}""",
        )
        assertNotNull(Eip712.digest(JSONObject(base.toString())))

        // A member the EIP712Domain type does not know.
        val unknownDomain = JSONObject(base.toString()).put("domain", JSONObject().put("name", "A").put("extra", 1))
        assertNull(Eip712.digest(unknownDomain))

        // A value the type does not give.
        val missing = JSONObject(base.toString()).put("message", JSONObject())
        assertNull(Eip712.digest(missing))

        // A primary type the list does not define.
        assertNull(Eip712.digest(JSONObject(base.toString()).put("primaryType", "Nope")))

        // An out-of-range uint8.
        val overflow = JSONObject(
            """{"domain":{"name":"A"},"types":{"M":[{"name":"x","type":"uint8"}]},"primaryType":"M","message":{"x":256}}""",
        )
        assertNull(Eip712.digest(overflow))

        // An address that is not 20 bytes.
        val badAddress = JSONObject(
            """{"domain":{"name":"A"},"types":{"M":[{"name":"x","type":"address"}]},"primaryType":"M","message":{"x":"0x1234"}}""",
        )
        assertNull(Eip712.digest(badAddress))

        // A fixed-length array with the wrong length.
        val badArray = JSONObject(
            """{"domain":{"name":"A"},"types":{"M":[{"name":"x","type":"uint256[2]"}]},"primaryType":"M","message":{"x":["1"]}}""",
        )
        assertNull(Eip712.digest(badArray))

        // No signature for an invalid key, and none for an unsupported input.
        assertNull(Eip712.signTypedData(ByteArray(32), base))
        assertNull(Eip712.signTypedData(key, unknownDomain))
    }
}
